// Подготовка отбора: проверка того, что прислала форма (браузер - недоверенный источник).
const inp = $input.first().json;
let f = {};
try { f = inp.filtersJson ? JSON.parse(inp.filtersJson) : {}; } catch (e) { f = {}; }

const onlyDigits = (v, lens) => { const s = String(v || '').replace(/\D/g, ''); return lens.includes(s.length) ? s : ''; };
const clean = arr => (Array.isArray(arr) ? arr : []).slice(0, 50)
  .map(o => ({ inn: onlyDigits(o && o.inn, [10, 12]), kpp: onlyDigits(o && o.kpp, [9]), name: String((o && o.name) || '').slice(0, 120) }))
  .filter(o => o.inn);
const isDate = s => /^\d{4}-\d{2}-\d{2}$/.test(String(s || '')) && !isNaN(Date.parse(s));

const orgs = clean(f.organizations), cps = clean(f.counterparties);
const dfrom = isDate(f.date_from) ? f.date_from : null, dto = isDate(f.date_to) ? f.date_to : null;

return [{ json: {
  chatInput: inp.chatInput, sessionId: inp.sessionId, user: inp.user, user_account: String(inp.user_account || ''),
  filters: { organizations: orgs, counterparties: cps, date_from: dfrom, date_to: dto }
} }];

// Ответ для формы в УНИФИЦИРОВАННОМ формате:
// { output, documents: [{ ref, key, kind, title, subtitle, url, fields: [{label, value, type}], fragments: [{index, label, text}] }], focus, files }
// Источник - результаты инструмента search_contracts из intermediateSteps (включено в опциях AI Agent).
const a = $input.first().json;
const output = String(a.output ?? a.text ?? '');

// ---------- ссылка на документ в 1С ----------
// Навигационная ссылка: e1c://server/<сервер>/<база>#e1cib/data/Справочник.ВнутренниеДокументы?ref=<ссылка>
const LINK_BASE = 'e1c://server/mbs-1cappc-01/DOC#e1cib/data/Справочник.ВнутренниеДокументы?ref=';
// В навигационной ссылке 1С ref - 32 hex-символа в особом порядке. Если contract_ref пришёл как GUID с дефисами
// (aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee), переставляем: dddd + eeeeeeeeeeee + cccc + bbbb + aaaaaaaa.
// Если уже 32 символа без дефисов - берём как есть.
const navRef = r => {
  const s = String(r || '').trim().toLowerCase();
  const m = /^([0-9a-f]{8})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{12})$/.exec(s);
  return m ? m[4] + m[5] + m[3] + m[2] + m[1] : s;
};
const linkOf = ref1c => (ref1c ? LINK_BASE + navRef(ref1c) : undefined);

// ---------- договор из подпроцесса поиска -> документ унифицированного формата ----------
const ru = d => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(d || '')); return m ? `${m[3]}.${m[2]}.${m[1]}` : (d || ''); };
const iso = d => { const m = /^(\d{4}-\d{2}-\d{2})/.exec(String(d || '')); return m ? m[1] : undefined; };
const field = (label, value, type) => (value === undefined || value === null || value === '') ? null : (type ? { label, value, type } : { label, value });
function toDocument(c) {
  const kind = c.document_type || (c.is_amendment ? 'Дополнительное соглашение' : 'Договор');
  const sum = c.sum === undefined || c.sum === null || c.sum === '' ? undefined : Number(String(c.sum).replace(/[\s ]/g, '').replace(',', '.'));
  return {
    ref: String(c.ref),
    key: c.number || String(c.ref),                       // агент пишет метки [номер#фрагмент]
    kind,
    title: (c.number ? '№ ' + c.number : 'Без номера') + (c.date ? ' от ' + ru(c.date) : ''),
    subtitle: [c.counterparty, c.title].filter(Boolean).join(' · '),
    url: linkOf(c.contract_ref),                          // форма делает упоминание документа в ответе гиперссылкой
    fields: [
      field('Контрагент', c.counterparty),
      field('ИНН контрагента', c.counterparty_inn),
      field('Организация', c.organization),
      field('Вид договора', c.contract_type),
      field('Сумма', Number.isFinite(sum) ? sum : c.sum, Number.isFinite(sum) ? 'money' : undefined),
      field('Валюта', c.currency),
      field('Действует с', iso(c.valid_from), 'date'),
      field('Действует по', iso(c.valid_to), 'date'),
    ].filter(Boolean),
    fragments: (c.fragments || []).map(f => ({ index: Number(f.chunk_index), text: String(f.text || '').replace(/\s+/g, ' ') })),
  };
}

// ---------- собираем договоры из всех вызовов search_contracts ----------
const found = new Map();   // ref -> договор с объединёнными фрагментами
const parse = v => { if (typeof v !== 'string') return v; try { return JSON.parse(v); } catch (e) { return null; } };
const walk = v => {
  v = parse(v);
  if (!v || typeof v !== 'object') return;
  if (Array.isArray(v)) { v.forEach(walk); return; }
  if (Array.isArray(v.contracts)) {
    for (const c of v.contracts) {
      if (!c || !c.ref) continue;
      const prev = found.get(c.ref);
      if (!prev) { found.set(c.ref, { ...c, fragments: [...(c.fragments || [])] }); continue; }
      const have = new Set(prev.fragments.map(f => f.chunk_index));
      for (const f of c.fragments || []) if (!have.has(f.chunk_index)) prev.fragments.push(f);
    }
  }
  for (const k of ['json', 'response', 'observation', 'output']) if (k in v && v[k] !== v) walk(v[k]);
};
for (const s of a.intermediateSteps || []) {
  if (s && s.action && s.action.tool && s.action.tool !== 'search_contracts') continue;
  walk(s && s.observation);
}

// сначала документы, на которые агент сослался в тексте, затем остальные найденные
const norm = s => String(s == null ? '' : s).toLowerCase().replace(/[\s№#]/g, '');
const text = norm(output);
const all = [...found.values()];
const cited = all.filter(c => c.number && text.includes(norm(c.number)));
const documents = [...cited, ...all.filter(c => !cited.includes(c))].slice(0, 20).map(toDocument);

return [{ json: {
  output,
  documents,
  focus: cited.length === 1 ? String(cited[0].ref) : null,
  files: []
} }];

// Текст документа для формы в УНИФИЦИРОВАННОМ формате:
// { ok: true, document: { ref, key, kind, title, subtitle, fields }, chunks: [{ index, label, text }] }  или  { ok: false, error }
const r = $input.first().json || {};
if (!r.ok) return [{ json: { ok: false, error: String(r.error || 'Документ не найден') } }];

// ---------- ссылка на документ в 1С ----------
// Навигационная ссылка: e1c://server/<сервер>/<база>#e1cib/data/Справочник.ВнутренниеДокументы?ref=<ссылка>
const LINK_BASE = 'e1c://server/mbs-1cappc-01/DOC#e1cib/data/Справочник.ВнутренниеДокументы?ref=';
// В навигационной ссылке 1С ref - 32 hex-символа в особом порядке. Если contract_ref пришёл как GUID с дефисами
// (aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee), переставляем: dddd + eeeeeeeeeeee + cccc + bbbb + aaaaaaaa.
// Если уже 32 символа без дефисов - берём как есть.
const navRef = r => {
  const s = String(r || '').trim().toLowerCase();
  const m = /^([0-9a-f]{8})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{4})-([0-9a-f]{12})$/.exec(s);
  return m ? m[4] + m[5] + m[3] + m[2] + m[1] : s;
};
const linkOf = ref1c => (ref1c ? LINK_BASE + navRef(ref1c) : undefined);

const h = r.header || {};
const ru = d => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(d || '')); return m ? `${m[3]}.${m[2]}.${m[1]}` : (d || ''); };
const iso = d => { const m = /^(\d{4}-\d{2}-\d{2})/.exec(String(d || '')); return m ? m[1] : undefined; };
const field = (label, value, type) => (value === undefined || value === null || value === '') ? null : (type ? { label, value, type } : { label, value });
const sum = h.sum === undefined || h.sum === null || h.sum === '' ? undefined : Number(String(h.sum).replace(/[\s ]/g, '').replace(',', '.'));

const document = {
  ref: String(r.ref || ''),
  key: h.number || String(r.ref || ''),
  kind: h.document_type || 'Договор',
  title: (h.number ? '№ ' + h.number : 'Без номера') + (h.date ? ' от ' + ru(h.date) : ''),
  subtitle: [h.counterparty, h.title].filter(Boolean).join(' · '),
  url: linkOf(r.contract_ref),
  fields: [
    field('Контрагент', h.counterparty),
    field('Сумма', Number.isFinite(sum) ? sum : h.sum, Number.isFinite(sum) ? 'money' : undefined),
    field('Валюта', h.currency),
    field('Действует с', iso(h.valid_from), 'date'),
    field('Действует по', iso(h.valid_to), 'date'),
  ].filter(Boolean),
};

let chunks = (r.chunks || []).map(c => ({ index: Number(c.i), text: String(c.text || '') }));
// чанков нет, но есть полный текст - отдаём его одним фрагментом
if (!chunks.length && r.full_text) chunks = [{ index: 0, label: '', text: String(r.full_text) }];

return [{ json: { ok: true, document, chunks } }];
